"""assistant.py: the stand-in "system under test" for Lab 1. You do not edit this file.

A real harness calls a prompt, a RAG pipeline or an agent. So that the lab runs offline and gives
the same numbers every time, this module plays a customer-support assistant instead:

    system = make_assistant(1)          # version 1, 2 or 3
    reply = system("Where is order #1234?", sample=0)

* `sample` is the index of the attempt (0, 1, 2, ...). Real models are random, so the same prompt can
  be answered well on one attempt and badly on the next. Here the randomness is seeded by
  (version, prompt, sample), so attempt 2 of a prompt always gives the same reply.
* Each prompt has a hidden difficulty, shared by the four paraphrases of one intent (the "group" in
  cases.jsonl). An attempt succeeds when the version's skill for that kind of request, plus a little
  attempt-to-attempt noise, beats the difficulty. So two versions mostly agree about what is easy.
* About 1 attempt in 70 raises TimeoutError, as a flaky network would. That is a harness
  problem, not a verdict on the model, and your runner must not crash on it.
* Version 3 is the planted trap: better at billing, worse at order-status JSON.
"""
import json
import os
import random

HERE = os.path.dirname(os.path.abspath(__file__))

# Skill per request kind (higher is better). Difficulty is roughly N(0, 1).
SKILL = {
    1: {"refund": 0.10, "status": 0.60, "billing": 0.00, "cancel": 0.05, "privacy": 0.35},
    2: {"refund": 0.30, "status": 0.70, "billing": 0.15, "cancel": 0.30, "privacy": 0.45},
    3: {"refund": 0.30, "status": -0.15, "billing": 1.40, "cancel": 0.30, "privacy": 0.45},
}
NOISE = 0.35        # attempt-to-attempt noise, in the same units as skill and difficulty
TIMEOUT_RATE = 1 / 70


class Assistant:
    def __init__(self, version, replies):
        self.version = version
        self.name = f"assistant-v{version}"
        self.replies = replies                    # prompt -> {"good", "bad", "d", "tag"}

    def __call__(self, prompt, sample=0):
        row = self.replies[prompt]
        seed = f"{self.version}|{prompt}|{sample}"
        if random.Random("timeout|" + seed).random() < TIMEOUT_RATE:
            raise TimeoutError(f"no reply within 30 s for {row['id']}")
        rng = random.Random(seed)
        ok = SKILL[self.version][row["tag"]] + rng.gauss(0, NOISE) > row["d"]
        return row["good"] if ok else row["bad"]


def make_assistant(version):
    """Version 1, 2 or 3 of the stand-in assistant."""
    with open(os.path.join(HERE, "replies.json"), encoding="utf-8") as f:
        by_id = json.load(f)
    with open(os.path.join(HERE, "cases.jsonl"), encoding="utf-8") as f:
        cases = [json.loads(line) for line in f if line.strip()]
    table = {c["input"]: dict(by_id[c["id"]], id=c["id"], tag=c["tags"][0]) for c in cases}
    return Assistant(version, table)
